import React from 'react';
import MotionReveal, { staggerDelay } from '../../motion/MotionReveal.jsx';
import OutlineIcon from '../icons/OutlineIcon.jsx';
import './WhyChooseUs.css';

const SUPPORT = [
  {
    tone: 'amber',
    icon: 'chat',
    title: '24 × 7 live chat',
    text: 'Counsellors on WhatsApp whenever a rank, form, or deadline pops up.',
    href: 'https://wa.link/czgq77',
    external: true,
  },
  {
    tone: 'blue',
    icon: 'phone',
    title: 'Schedule a call',
    text: 'Talk through streams, colleges, and cutoffs with a real advisor.',
    href: 'tel:+919008804368',
  },
  {
    tone: 'green',
    icon: 'mail',
    title: 'Email support',
    text: 'Send documents or questions — we reply with a clear next step.',
    href: 'mailto:info@mapmycareer360.com',
  },
];

export default function WhyChooseUs() {
  return (
    <section className="section mmc-why-section">
      <div className="container">
        <MotionReveal className="section-title">
          <p className="mmc-section-eyebrow">Support</p>
          <h2>Students love our <span>guidance</span></h2>
        </MotionReveal>
        <div className="mmc-why-grid">
          {SUPPORT.map((r, i) => (
            <MotionReveal
              as="a"
              href={r.href}
              target={r.external ? '_blank' : undefined}
              rel={r.external ? 'noreferrer' : undefined}
              className={`card mmc-why-card mmc-why-card--${r.tone}`}
              key={r.title}
              delay={staggerDelay(i)}
            >
              <span className="mmc-why-icon"><OutlineIcon name={r.icon} size={22} /></span>
              <h4>{r.title}</h4>
              <p>{r.text}</p>
            </MotionReveal>
          ))}
        </div>
      </div>
    </section>
  );
}
